package Hello_world;
/*write a java code to print 
12345
246810
3691215
48121620
510152025

 * 
 */
public class A011_pattern {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		for (int i = 1; i <=5; i++) {
			for (int j = 1; j <=5; j++) {
				
				System.out.print(i*j);
			}
			System.out.println();
			
		}

	}

}
